<?php
require_once __DIR__.'/includes/functions.php';require_customer();verify_csrf();$uid=(int)current_user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){$pid=(int)($_POST['product_id']??0);$s=$conn->prepare('SELECT id FROM products WHERE id=? AND is_active=1');$s->bind_param('i',$pid);$s->execute();if($s->get_result()->fetch_assoc()){$s=$conn->prepare('INSERT IGNORE INTO wishlist_items(user_id,product_id) VALUES(?,?)');$s->bind_param('ii',$uid,$pid);$s->execute();flash('Product saved to wishlist.');}redirect('wishlist.php');}
if(isset($_GET['remove'])){$pid=(int)$_GET['remove'];$s=$conn->prepare('DELETE FROM wishlist_items WHERE user_id=? AND product_id=?');$s->bind_param('ii',$uid,$pid);$s->execute();flash('Product removed from wishlist.');redirect('wishlist.php');}
$s=$conn->prepare('SELECT p.*,c.name category_name FROM wishlist_items w JOIN products p ON p.id=w.product_id JOIN categories c ON c.id=p.category_id WHERE w.user_id=? AND p.is_active=1 ORDER BY w.created_at DESC');$s->bind_param('i',$uid);$s->execute();$products=$s->get_result()->fetch_all(MYSQLI_ASSOC);render_header('Wishlist');?><div class="page-heading"><span class="eyebrow">SAVED FOR LATER</span><h1>Your wishlist</h1></div><?php if(!$products):?><div class="empty-state"><div class="empty-icon">♡</div><h2>No saved products yet</h2><a class="button" href="<?=e(url())?>">Discover products</a></div><?php else:?><div class="product-grid"><?php foreach($products as $p):?><article class="product-card"><a class="product-image" href="<?=e(url('product.php?id='.$p['id']))?>"><img src="<?=e(image_path($p['image']))?>" alt="<?=e($p['name'])?>"></a><div class="product-info"><a class="product-name" href="<?=e(url('product.php?id='.$p['id']))?>"><?=e($p['name'])?></a><div class="product-bottom"><b><?=money($p['price'])?></b><a href="<?=e(url('wishlist.php?remove='.$p['id']))?>">Remove</a></div><form method="post" action="<?=e(url('cart.php'))?>"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="button full">Add to cart</button></form></div></article><?php endforeach;?></div><?php endif;?><?php render_footer();?>
